effect.shader:
float gmHash(float n){ return fract(sin(n)*43758.5453123); }
float gmHash2(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
float gmRainLayer(vec2 uv, float cols, float speed, float segFrac, float widthPx, float seed, float t, float aspect){
vec2 q = uv;
q.x *= cols;
q.y = q.y * cols / max(aspect * 0.35, 0.5);
float col = floor(q.x);
float fx = fract(q.x);
float h = gmHash(col + seed * 37.0);
float h2 = gmHash(col * 1.7 + seed * 91.0);
float fall = fract(q.y * (0.6 + h * 0.8) - t * speed * (0.7 + h2 * 0.9) - h * 7.0);
float seg = smoothstep(0.0, 0.06, fall) * smoothstep(segFrac, segFrac * 0.72, fall) * smoothstep(1.0, 0.94, fall);
float line = exp(-pow((fx - (0.25 + 0.5 * h)) / max(widthPx / cols, 0.02), 2.0));
return seg * line * (0.45 + 0.55 * h2);
}
float gmSplash(vec2 uv, float cols, float speed, float t, float seed, float aspect, float scale){
vec2 p = uv * vec2(cols, cols / max(aspect, 0.5));
vec2 cell = floor(p);
vec2 f = fract(p) - 0.5;
float h = gmHash2(cell + seed);
float slot = floor(t * speed + h * 16.0);
float hr = gmHash2(cell * 3.1 + vec2(slot, slot * 0.7));
float ringT = fract(t * speed + h * 16.0);
float d = length(f * vec2(1.0, aspect));
float r = (0.08 + 0.30 * ringT) * scale;
float ring = smoothstep(0.05, 0.0, abs(d - r)) * (1.0 - ringT);
return ring * step(0.55, hr);
}
void main(){
vec2 uv = acScreenNorm;
vec4 src = texture2DCv(inputImg.texture, uv);
float aspect = max(getTexSize(inputImg.size).x / max(getTexSize(inputImg.size).y, 1.0), 0.5);
float a = radians(rainAngle);
vec2 dir = vec2(cos(a), -sin(a));
vec2 ruv = vec2(dot(uv, vec2(dir.x, -dir.y)), dot(uv, vec2(dir.y, dir.x)));
float amt = rainAmount * 0.01;
float seg = clamp(streakLen / max(getTexSize(inputImg.size).y, 1.0) * 22.0, 0.08, 0.95);
float w = streakWidth;
float r1 = gmRainLayer(ruv, 42.0, rainSpeed * 0.9, seg, w * 1.2, 1.0, acTime, aspect);
float r2 = gmRainLayer(ruv + 0.37, 30.0, rainSpeed * 1.15, seg * 1.15, w, 2.0, acTime, aspect);
float r3 = gmRainLayer(ruv + 0.71, 20.0, rainSpeed * 1.45, seg * 1.3, w * 0.85, 3.0, acTime, aspect);
float rain = (r1 * 0.9 + r2 * 1.1 + r3 * 1.3) * amt * rainBright;
float splash = 0.0;
if (splashes) {
float s1 = gmSplash(uv + 0.13, 14.0, 1.6, acTime, 5.0, aspect, splashScale);
float s2 = gmSplash(uv - 0.44, 9.0, 1.1, acTime, 9.0, aspect, splashScale);
splash = (s1 + s2 * 0.8) * splashBright * amt;
}
vec3 add = rainTint.rgb * (rain + splash * 0.8);
vec3 col = src.rgb * src.a + add * src.a;
gl_FragColor = vec4(col, src.a);
}
